import{_ as a,o as l,c as t,ae as i}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"Scheduled Accounting","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/12-scheduled-accounting-guide.md","filePath":"v1/en/guide/12-scheduled-accounting-guide.md"}'),n={name:"v1/en/guide/12-scheduled-accounting-guide.md"};function o(r,e,s,u,d,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="scheduled-accounting" tabindex="-1">Scheduled Accounting <a class="header-anchor" href="#scheduled-accounting" aria-label="Permalink to &quot;Scheduled Accounting&quot;">​</a></h1><h2 id="_1-what-this-feature-is" tabindex="-1">1. What this feature is <a class="header-anchor" href="#_1-what-this-feature-is" aria-label="Permalink to &quot;1. What this feature is&quot;">​</a></h2><p>Scheduled accounting lets you set up rules for recurring income/expenses (such as rent, utilities, subscriptions, and salary). Koala will automatically create bills based on those rules, reducing repetitive manual entry.</p><h2 id="_2-when-to-use-it" tabindex="-1">2. When to use it <a class="header-anchor" href="#_2-when-to-use-it" aria-label="Permalink to &quot;2. When to use it&quot;">​</a></h2><ul><li>Monthly rent, mortgage payments, credit card repayments</li><li>Weekly commuting costs or fixed meal allowances</li><li>Monthly subscriptions (streaming, cloud storage, etc.)</li><li>Monthly fixed income (salary, allowances, etc.)</li></ul><h2 id="_3-how-to-use-it" tabindex="-1">3. How to use it <a class="header-anchor" href="#_3-how-to-use-it" aria-label="Permalink to &quot;3. How to use it&quot;">​</a></h2><ol><li>Go to <strong>Settings</strong> and find <strong>Scheduled accounting</strong></li><li>Create a new schedule rule and fill in: <ul><li>Type: Expense / Income</li><li>Category</li><li>Amount</li><li>Account</li><li>Tags and note (optional)</li><li>Frequency: Daily / Weekly / Monthly (choose the date or weekday based on the rule)</li><li>Start/end date: start date is required; end date is optional (auto stops when it expires)</li></ul></li><li>After saving, the rule will appear in the scheduled accounting list</li><li>When the trigger time arrives, Koala will generate bills based on the rule</li></ol><h2 id="_4-rules-and-notes" tabindex="-1">4. Rules and notes <a class="header-anchor" href="#_4-rules-and-notes" aria-label="Permalink to &quot;4. Rules and notes&quot;">​</a></h2><ul><li>Bills generated by scheduled accounting are the same as manually created bills: they appear in the list and are included in statistics.</li><li>If you don’t open the app for a long time, some devices may not generate bills exactly on time. The next time you open the app, Koala will catch up and create any due bills that were not generated (to avoid missing entries).</li><li>Review your rules periodically to ensure the amount, category, and account still match reality (for example, rent changes or you switch cards).</li><li>After you pause/terminate a rule, no more bills will be created. Re-enabling it will continue from the next cycle.</li></ul><h2 id="_5-faq" tabindex="-1">5. FAQ <a class="header-anchor" href="#_5-faq" aria-label="Permalink to &quot;5. FAQ&quot;">​</a></h2><h3 id="q1-what-if-a-scheduled-bill-was-generated-incorrectly" tabindex="-1">Q1: What if a scheduled bill was generated incorrectly? <a class="header-anchor" href="#q1-what-if-a-scheduled-bill-was-generated-incorrectly" aria-label="Permalink to &quot;Q1: What if a scheduled bill was generated incorrectly?&quot;">​</a></h3><p>Scheduled bills can be edited or deleted just like normal bills. If it happens often, adjust the corresponding rule (amount/frequency/account, etc.).</p><h3 id="q2-if-i-change-a-rule-will-previously-generated-bills-update-automatically" tabindex="-1">Q2: If I change a rule, will previously generated bills update automatically? <a class="header-anchor" href="#q2-if-i-change-a-rule-will-previously-generated-bills-update-automatically" aria-label="Permalink to &quot;Q2: If I change a rule, will previously generated bills update automatically?&quot;">​</a></h3><p>No. Rule changes only affect bills generated in the future. Historical bills remain unchanged for traceability.</p><h3 id="q3-will-multiple-bills-be-generated-on-the-same-day" tabindex="-1">Q3: Will multiple bills be generated on the same day? <a class="header-anchor" href="#q3-will-multiple-bills-be-generated-on-the-same-day" aria-label="Permalink to &quot;Q3: Will multiple bills be generated on the same day?&quot;">​</a></h3><p>If you have multiple rules, Koala will generate bills for each rule. For the same rule, Koala tries to avoid generating duplicates.</p>',16)])])}const m=a(n,[["render",o]]);export{g as __pageData,m as default};
